require_once __DIR__.'/_layout.php';
try{$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if(!$id)throw new InvalidArgumentException('not found');$file=inspectionPhotoAuthorizeRead($id);$extensions=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];header('Content-Type: '.$file['mime']);header('Content-Length: '.filesize($file['path']));header('Content-Disposition: inline; filename="inspection-photo-'.(int)$id.'.'.$extensions[$file['mime']].'"');header('Cache-Control: private, no-store, max-age=0');header('X-Content-Type-Options: nosniff');readfile($file['path']);}catch(Throwable){protectedFileNotFound();}
